def parse_duration(s: str) -> int:
    if not s or s[-1] == '.':
        raise ValueError("Invalid input format")

    # Split into hours, minutes, and seconds
    parts = s.split('h')
    if len(parts) != 2:
        raise ValueError("Invalid input format")
    h_str, m_str = parts[0].split('m')
    if len(m_str) != 2 or m_str[0] == m_str[1]:
        raise ValueError("Invalid input format")
    s_str = s[-1].split('s')
    if len(s_str) != 2 or s_str[0] == s_str[1]:
        raise ValueError("Invalid input format")
    seconds = int(s_str[0]) * 1000 + int(s_str[1]) * 1000

    total = 0
    if h_str > 0:
        total += int(h_str) * 3600
    if m_str > 0:
        total += int(m_str) * 60
    if seconds > 0:
        total += seconds

    return int(total)

